return items.map(item => {
  function extractSalaryFromDescription(description) {
    if (!description) return "";
    // Matches common salary patterns
    const salaryRegex = /\$\d{1,3}(?:,\d{3})*(?:\.\d+)?\s*-\s*\$\d{1,3}(?:,\d{3})*(?:\.\d+)?\s*(an hour|per hour|hourly|a year|annually)?/i;
    const match = description.match(salaryRegex);
    return match ? match[0] : "";
  }
  const salary = item.json.salary || extractSalaryFromDescription(item.json.description);
  return {
    json: {
      ...item.json,
      salary
    }
  };
});

return items.map((item, index) => {
  let content = {};

  try {
    if (item.json && item.json.choices && item.json.choices[0] && item.json.choices[0].message) {
      content = item.json.choices[0].message.content || {};
    }
  } catch(e) {
    content = {};
  }

  // Access original "Extract Data" node for Job description
  const extractData = $('Extract Data').all()[index].json;
  const jobDescription = extractData['Job description'] || content.Job_description || '';

  // Salary fallback with regex
  let salary = content.Salary || extractData.Salary || null;

  if (!salary && jobDescription) {
    const salaryMatch = jobDescription.match(/\$?([\d,]+\.?\d*)\s*-?\s*\$?([\d,]+\.?\d*)?\s*(an hour|per hour|\/hour|\/hr|hourly)/i);
    if (salaryMatch) {
      const rate1 = salaryMatch[1].replace(/,/g, '');
      const rate2 = salaryMatch[2] ? salaryMatch[2].replace(/,/g, '') : rate1;
      salary = salaryMatch[2] ? `$${rate1} - $${rate2} an hour` : `$${rate1} an hour`;
    }
  }

  return {
    json: {
      is_qualified_lead: content.is_qualified_lead !== undefined ? content.is_qualified_lead : null,
      industry_specialized_detected: content.industry_specialized_detected !== undefined ? content.industry_specialized_detected : null,
      company: content.company || extractData.company || null,
      job_title: content.job_title || extractData.job_title || null,
      location: content.location || extractData.location || null,
      Salary: salary,
      Job_description: jobDescription,
      notes: content.notes || null,
      Hook_intro: content.Hook_intro || null,
      duties_core_covered: Array.isArray(content.duties_core_covered) ? content.duties_core_covered : [],
      duties_core_missing: Array.isArray(content.duties_core_missing) ? content.duties_core_missing : [],
      estimatedannualsavings: content.estimatedannualsavings || null,
      estimatedannualcosttocompany: content.estimatedannualcosttocompany || null,
      salaryHourly: content.salaryHourly || null,
      id: extractData.id || null,
      url: extractData.url || null,
      positionName: extractData.positionName || null,
      Date_posted: extractData['Date posted'] || null
    }
  };
});

return items.map(item => {
  const salary = item.json.Salary || '';
  let hourlyRate = null;
  let annualCost = null;
  let annualSavings = null;

  // Extract hourly rate from salary string
  const hourlyMatch = salary.match(/\$?([\d,]+\.?\d*)\s*-?\s*\$?([\d,]+\.?\d*)?\s*(an hour|per hour|\/hour|\/hr|hourly)/i);

  if (hourlyMatch) {
    const rate1 = parseFloat(hourlyMatch[1].replace(/,/g, ''));
    const rate2 = hourlyMatch[2] ? parseFloat(hourlyMatch[2].replace(/,/g, '')) : rate1;
    hourlyRate = (rate1 + rate2) / 2;

    // Annual cost calculation: hourly × 2080 hours/year × 1.3 (benefits multiplier)
    annualCost = Math.round(hourlyRate * 2080 * 1.3);

    // Estimated savings: 70% of annual cost (AI replaces 70% of duties)
    annualSavings = Math.round(annualCost * 0.7);
  }

  return {
    json: {
      ...item.json,
      salaryHourly: hourlyRate ? `$${hourlyRate.toFixed(2)}` : 'Not specified',
      estimatedannualcosttocompany: annualCost ? `$${annualCost.toLocaleString()}` : 'Contact for quote',
      estimatedannualsavings: annualSavings ? `$${annualSavings.toLocaleString()}` : 'Contact for details'
    }
  };
});

// This runs once per item
const item = $input.item.json;
const structure = item.structure;
let markdown = '';

for (let i = 0; i < structure.length; i++) {
  const section = structure[i];
  const sectionName = section.section;
  const data = section.data;

  // Opening section: always H1 headline with special colon handling
  if (sectionName === 'headline') {
    const headline = data.headline || '';

    // Check if headline contains a colon
    if (headline.includes(':')) {
      const parts = headline.split(':');
      const h1Part = parts[0].trim();
      const h2Part = parts.slice(1).join(':').trim(); // Handle multiple colons

      // H1 for first part
      markdown += `# ${h1Part}\n\n`;
      // H2 for second part (if not empty)
      if (h2Part) {
        markdown += `## ${h2Part}\n\n`;
      }
    } else {
      // No colon: render entire headline as H1
      markdown += `# ${headline}\n\n`;
    }

    // Opening hook paragraph (if present)
    if (data.openingHook && data.openingHook.trim() !== '') {
      markdown += `${data.openingHook}\n\n`;
    }

    // Triple line break after opening section
    markdown += '\n';
  }
  // CTA section: should always be H2, with extra spacing before
  else if (sectionName === 'cta') {
    // Add extra linebreak separation before CTA section, unless just after headline
    if (i !== 1) {
      markdown += '\n\n';
    }
    if (typeof data === 'object' && data !== null) {
      if (data.headline && data.headline.trim() !== '') {
        markdown += `## ${data.headline}\n\n`;
      }
      if (data.content && data.content.trim() !== '') {
        // Optional: bold numbers and key phrases in CTA content
        const ctaContent = data.content.replace(
          /(\$[\d,]+|\d+-minute|\d+\s?%)/g, '**$1**'
        );
        markdown += `${ctaContent}\n\n`;
      }
    } else if (typeof data === 'string' && data.trim() !== '') {
      markdown += `${data}\n\n`;
    }
  }
  // All other sections: H2 headlines
  else {
    if (typeof data === 'object' && data !== null) {
      if (data.headline && data.headline.trim() !== '') {
        markdown += `## ${data.headline}\n\n`;
      }
      if (data.content && data.content.trim() !== '') {
        markdown += `${data.content}\n\n`;
      }
    } else if (typeof data === 'string' && data.trim() !== '') {
      markdown += `${data}\n\n`;
    }
  }
}

// Final cleanup: ensure max 3 consecutive newlines, trim trailing space
markdown = markdown.replace(/\n{4,}/g, '\n\n\n').trim();

return {
  json: {
    markdown: markdown
  }
};

