// This runs once per item
const item = $input.item.json;

// Extract the nested content object
const content = item.choices[0].message.content;

// Always extract headline and openingHook
const headline = content.headline || "";
const openingHook = content.openingHook || "";

// The 3 sections that will be shuffled - PRESERVE FULL STRUCTURE
const sections = [
  { 
    key: "coreValueProp", 
    data: typeof content.coreValueProp === 'object' && content.coreValueProp !== null
      ? content.coreValueProp  // Keep as object
      : content.coreValueProp  // Keep as string
  },
  { 
    key: "capabilities", 
    data: typeof content.capabilities === 'object' && content.capabilities !== null
      ? content.capabilities
      : content.capabilities
  },
  { 
    key: "uniqueAdvantages", 
    data: typeof content.uniqueAdvantages === 'object' && content.uniqueAdvantages !== null
      ? content.uniqueAdvantages
      : content.uniqueAdvantages
  }
];

// Shuffle the 3 sections randomly
const shuffled = sections.sort(() => Math.random() - 0.5);

// CTA data - PRESERVE STRUCTURE
const cta = typeof content.cta === 'object' && content.cta !== null
  ? content.cta
  : content.cta;

// Randomly decide if CTA goes in position 4 or 5 (last)
const ctaPosition = Math.random() < 0.5 ? 4 : 5;

// Build the ordered structure
const orderedSections = [];

// Position 1: always headline + openingHook
orderedSections.push({
  section: "headline",
  data: { headline, openingHook }
});

// Positions 2, 3, 4 or 2, 3, 4, 5 depending on CTA placement
if (ctaPosition === 4) {
  orderedSections.push({ section: shuffled[0].key, data: shuffled[0].data });
  orderedSections.push({ section: shuffled[1].key, data: shuffled[1].data });
  orderedSections.push({ section: "cta", data: cta });
  orderedSections.push({ section: shuffled[2].key, data: shuffled[2].data });
} else {
  orderedSections.push({ section: shuffled[0].key, data: shuffled[0].data });
  orderedSections.push({ section: shuffled[1].key, data: shuffled[1].data });
  orderedSections.push({ section: shuffled[2].key, data: shuffled[2].data });
  orderedSections.push({ section: "cta", data: cta });
}

// Return single item with structured output
return {
  json: {
    proposalId: item.id,
    model: item.model,
    structure: orderedSections,
    // Preserve original for reference
    original: content
  }
};

return items.map(item => {
  // Use 'id' as the doc ID key (check your input, should be present)
  const docId = item.json.id;
